fn choose_num(x: i8, y: i8) -> i8 {
    // If the lower bound exceeds the upper bound, there's no valid interval.
    if x > y {
        return -1;
    }
    // Determine the largest even number ≤ y.
    let candidate = if y % 2 == 0 {
        y
    } else {
        y - 1
    };
    // If that candidate still lies within [x, y], return it; otherwise, no even numbers in the interval.
    if candidate >= x {
        candidate
    } else {
        -1
    }
}

